const $=s=>document.querySelector(s);
const KEY='political-archive-v1';let storageOK=true;let memoryState=null;
function readState(){if(!storageOK&&memoryState)return JSON.parse(memoryState);try{const s=JSON.parse(localStorage.getItem(KEY));const owned={};if(s&&s.owned)for(const c of CARDS){const n=s.owned[c.id];if(Number.isSafeInteger(n)&&n>0)owned[c.id]=n;}return {owned,packs:Number.isSafeInteger(s?.packs)&&s.packs>=0?s.packs:0,points:Number.isSafeInteger(s?.points)&&s.points>=0?s.points:0,quizzesCompleted:Number.isSafeInteger(s?.quizzesCompleted)&&s.quizzesCompleted>=0?s.quizzesCompleted:0,quiz:validateQuiz(s?.quiz)?s.quiz:null};}catch{return {owned:{},packs:0,points:0,quizzesCompleted:0,quiz:null};}}
let state=readState();const count=id=>state.owned[id]||0;
function persist(){memoryState=JSON.stringify(state);try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Browser storage unavailable. Keep an export before leaving.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
const packs=[{id:'ideas',name:'The idea makers',title:'THE IDEA<br>MAKERS',symbol:'✳',color:'#afa5c4',ink:'#302b3c',desc:'Philosophers, economists, and political theory.',category:'Thinkers'},{id:'leaders',name:'Seats of power',title:'SEATS OF<br>POWER',symbol:'♜',color:'#c9ab87',ink:'#3e3022',desc:'Heads of state, reformers, and rulers.',category:'Leaders'},{id:'turning',name:'Turning points',title:'TURNING<br>POINTS',symbol:'↗',color:'#98b4af',ink:'#223a35',desc:'Movements, revolutions, and political conflict.',category:'turning'}];
packs.push(...THEMED_PACKS);
const poolFor=p=>THEME_POOLS[p.id]?CARDS.filter(c=>THEME_POOLS[p.id].includes(c.name)||c.themes?.includes(p.id)||(p.id==='art'&&c.category==='Artists')):CARDS.filter(c=>!p.category||c.category===p.category||(p.category==='turning'&&['Movements','Conflict'].includes(c.category)));
$('#pack-grid').innerHTML=packs.map(p=>`<article class="pack-slot"><div class="pack-art" data-design="${p.id}" aria-hidden="true" style="--pack:${p.color};--pack-ink:${p.ink}"><small>THE POLITICAL ARCHIVE</small><span class="pack-symbol">${p.symbol}</span><span class="pack-title">${p.title}</span><small class="pack-series">SERIES 001 · FIVE COLLECTIBLE CARDS</small></div><h3>${p.name}</h3><p>${p.desc}<br>${poolFor(p).length} possible figures</p><button class="open-btn" data-pack="${p.id}">Open packet <span>100 pts ↗</span></button></article>`).join('');
function escapeText(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function cardHTML(c,options={}){const n=count(c.id),portrait=PORTRAITS[c.id];return `<button class="archive-card ${options.catalog&&!n?'missing':''} ${options.revealed?'reveal-enter':''}" data-card="${c.id}" data-rarity="${c.rarity}" aria-label="${escapeText(c.name)}, ${c.rarity}, ${n} owned"><div class="card-top"><span>PA / ${String(c.number).padStart(3,'0')}</span><span>${c.category.toUpperCase()}</span></div>${options.isNew?'<b class="new-label card-new">NEW</b>':''}<div class="card-seal portrait-frame">${portrait?`<img src="${escapeText(portrait.src)}" alt="Portrait of ${escapeText(c.name)}" loading="lazy" decoding="async">`:'<span class="portrait-unavailable">Portrait unavailable</span>'}</div><h3>${escapeText(c.name)}</h3><span class="card-role">${escapeText(c.role)}</span><span class="card-region">${escapeText(c.region)}</span><div class="card-bottom"><span class="rarity-tag">${c.rarity}</span><span class="copies">${n?'×'+n:'NOT OWNED'}</span></div></button>`;}
function stats(){ $('#points-balance').textContent=state.points.toLocaleString();document.querySelectorAll('[data-pack]').forEach(b=>{b.innerHTML=(state.points>=PACK_COST?'Open packet':'Earn points')+'<span>100 pts ↗</span>';});const unique=CARDS.filter(c=>count(c.id)>0).length,total=Object.values(state.owned).reduce((a,b)=>a+b,0);$('#nav-count').textContent=unique;$('#unique-stat').textContent=unique;$('#total-stat').textContent=total;$('#pack-stat').textContent=state.packs;$('#completion').textContent=`${unique} / ${CARDS.length}`;$('#progress-fill').style.width=`${unique/CARDS.length*100}%`;$('#roster-label').textContent=`${CARDS.length} FIGURES · ONE ARCHIVE`;$('#featured').innerHTML=['Franklin D. Roosevelt','Karl Marx','Frida Kahlo','Mahatma Gandhi','Georges Sorel'].map(name=>cardHTML(CARDS.find(c=>c.name===name))).join('');}
function catalog(){let list=CARDS.filter(c=>{let term=$('#search').value.trim().toLocaleLowerCase();return (!term||[c.name,c.region,c.bio,c.category,c.role,c.id,c.name==='Abdullah Öcalan'?'apo pkk':'',c.name==='Franklin D. Roosevelt'?'fdr':''].join(' ').toLocaleLowerCase().includes(term))&&(!$('#category').value||c.category===$('#category').value)&&(!$('#rarity').value||c.rarity===$('#rarity').value)&&({all:true,owned:count(c.id)>0,missing:count(c.id)===0,duplicates:count(c.id)>1}[$('#ownership').value]);});if($('#sort').value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));if($('#sort').value==='copies')list.sort((a,b)=>count(b.id)-count(a.id)||a.number-b.number);$('#catalog').innerHTML=list.map(c=>cardHTML(c,{catalog:true})).join('');$('#result-count').textContent=`${list.length} of ${CARDS.length} cards · ${CARDS.filter(c=>count(c.id)>1).length} with duplicates`;$('#empty').hidden=!!list.length;}
function tab(id){if(!['packs','collection','quiz'].includes(id))id='packs';document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==id);document.querySelectorAll('.nav').forEach(el=>{el.classList.toggle('active',el.dataset.tab===id);if(el.dataset.tab===id)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});if(id==='collection')catalog();if(id==='quiz'&&typeof renderQuiz==='function')renderQuiz();history.replaceState(null,'','#'+id);window.scrollTo({top:0});}
document.querySelectorAll('[data-tab],[data-go]').forEach(b=>b.onclick=()=>tab(b.dataset.tab||b.dataset.go));
['search','category','rarity','ownership','sort'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',catalog));
let currentPack,draws=[],revealed=new Set();
function random(){const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]/4294967296;}
function draw(pool){const weights=RARITY_WEIGHTS,tiers=rarities.map((rarity,i)=>({cards:pool.filter(c=>c.rarity===rarity),weight:weights[i]})).filter(t=>t.cards.length);let r=random()*tiers.reduce((s,t)=>s+t.weight,0);for(const t of tiers){r-=t.weight;if(r<0)return t.cards[Math.floor(random()*t.cards.length)];}const last=tiers.at(-1).cards;return last[Math.floor(random()*last.length)];}
function openPack(id){state=readState();currentPack=packs.find(p=>p.id===id);if(!currentPack)return false;if(state.points<PACK_COST){stats();if($('#opening').open)$('#opening').close();tab('quiz');toast('A packet costs 100 points. Complete a test to earn points.');return false;}state.points-=PACK_COST;resetCelebration();const pool=poolFor(currentPack);revealed.clear();const before={...state.owned};draws=Array.from({length:5},()=>draw(pool)).map(c=>({card:c,isNew:!before[c.id]}));for(const d of draws)state.owned[d.card.id]=count(d.card.id)+1;state.packs++;persist();stats();catalog();$('#opening-label').textContent=`${currentPack.name.toUpperCase()} · PACKET ${String(state.packs).padStart(3,'0')}`;$('#drawn').innerHTML=draws.map((d,i)=>`<button class="archive-card card-back" data-reveal="${i}" aria-label="Reveal card ${i+1}"><span class="brandmark">PA</span><p>THE POLITICAL<br>ARCHIVE</p><small>${String(i+1).padStart(2,'0')} / 05 · TAP TO REVEAL</small></button>`).join('');$('#reveal-all').hidden=false;$('#again').hidden=true;$('#reveal-hint').textContent='Tap a card to turn it over, or reveal them all.';$('#save-note').textContent=storageOK?'All five cards are saved to your collection immediately.':'Browser storage unavailable. Export your collection before leaving.';$('#save-note').classList.toggle('storage-error',!storageOK);if(!$('#opening').open)$('#opening').showModal();}
function reveal(i){if(revealed.has(i))return;revealed.add(i);const d=draws[i],old=$(`[data-reveal="${i}"]`);old.outerHTML=cardHTML(d.card,{isNew:d.isNew,revealed:true});celebrateCard(d.card);if(revealed.size===5){$('#reveal-all').hidden=true;$('#again').hidden=false;const n=new Set(draws.filter(d=>d.isNew).map(d=>d.card.id)).size;$('#reveal-hint').textContent=n?`${n} new figure${n===1?'':'s'} added to your archive.`:'Five more cards for your archive. Duplicates are counted.';}}
document.addEventListener('click',e=>{const pack=e.target.closest('[data-pack]');if(pack)openPack(pack.dataset.pack);const back=e.target.closest('[data-reveal]');if(back)reveal(Number(back.dataset.reveal));const card=e.target.closest('[data-card]');if(card)showDetails(card.dataset.card);});
function showDetails(id){const c=CARDS.find(c=>c.id===id);$('#detail-content').innerHTML=`<div>${cardHTML(c)}</div><div><p class="eyebrow">${c.category.toUpperCase()} / ${c.id.toUpperCase()}</p><h2>${escapeText(c.name)}</h2><p class="detail-role">${escapeText(c.role)}</p><p>${escapeText(c.bio)}</p><p>${escapeText(c.region)}<br>${count(id)} ${count(id)===1?'copy':'copies'} in your collection</p><a target="_blank" rel="noopener noreferrer" href="${escapeText(PORTRAITS[id]?.article||'https://en.wikipedia.org/wiki/'+encodeURIComponent(c.name.replaceAll(' ','_')))}">Explore historical context ↗</a>${PORTRAITS[id]?`<p class="portrait-credit">${escapeText(PORTRAITS[id].attribution||'Original credit and usage terms at source')}<br><a target="_blank" rel="noopener noreferrer" href="${escapeText(PORTRAITS[id].credit)}">Portrait source &amp; license ↗</a></p>`: ''}</div>`;if(!$('#details').open)$('#details').showModal();}
$('#reveal-all').onclick=()=>draws.forEach((_,i)=>reveal(i));$('#again').onclick=()=>openPack(currentPack.id);$('#to-collection').onclick=()=>{$('#opening').close();tab('collection');};$('#about').onclick=()=>$('#about-dialog').showModal();document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
$('#export').onclick=()=>{const data={title:'The Political Archive',exportedAt:new Date().toISOString(),packetsOpened:state.packs,cards:CARDS.map(c=>({id:c.id,name:c.name,category:c.category,rarity:c.rarity,copies:count(c.id)}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='political-archive-collection.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Collection exported.');};
stats();catalog();tab(location.hash.slice(1));
